function findMatch(
  targets: ResearchTarget[],
  expectation: Expectation,
): ResearchTarget | null {
  const needles = expectation.needles.map((n) => n.toLowerCase());
  return (
    targets.find((t) => {
      const hay = haystack(t);
      return needles.every((n) => hay.includes(n));
    }) ?? null
  );
