/** Rhythm forecasts contain seconds and counts only; no manuscript state. */
import { quantile, type FlowProfile } from "./flow-profile";
import type { Interval } from "./extraction";
import type { FlowMode, KeySample } from "./flow-state";

export const MIN_RHYTHM_HISTORY = 8;
export type PauseDecision = "hold" | "release" | "timer";
export interface RhythmEstimate {
  focus: Interval | null;
  pause: Interval | null;
}

/** Remaining seconds, conditional on having already lasted `elapsedSeconds`. */
export function remainingQuantiles(
  durationsMs: readonly number[],
  elapsedSeconds: number,
  minimum = MIN_RHYTHM_HISTORY,
): Interval | null {
  if (!Number.isFinite(elapsedSeconds) || elapsedSeconds < 0) return null;
  const remaining = durationsMs
    .filter((ms) => Number.isFinite(ms) && ms / 1000 > elapsedSeconds)
    .map((ms) => ms / 1000 - elapsedSeconds);
  if (remaining.length < Math.max(1, minimum)) return null;
  return {
    p10: quantile(remaining, 0.1)!,
    median: quantile(remaining, 0.5)!,
    p90: quantile(remaining, 0.9)!,
  };
}

export function rhythmBaseline(
  profile: FlowProfile,
  runSeconds: number,
  pauseSeconds: number,
): RhythmEstimate {
  return {
    focus: remainingQuantiles(profile.runs, runSeconds),
    pause: remainingQuantiles(profile.pauses, pauseSeconds),
  };
}

export function validInterval(value: Interval | null): value is Interval {
  return (
    !!value &&
    [value.p10, value.median, value.p90].every(
      (n) => Number.isFinite(n) && n >= 0,
    ) &&
    value.p10 <= value.median &&
    value.median <= value.p90
  );
}

/** Both estimates are remaining durations at the time they were made. */
export function pauseDecision(
  estimate: RhythmEstimate,
  exitPauseMs: number,
  ageSeconds = 0,
): PauseDecision {
  const { focus, pause } = estimate;
  if (!validInterval(focus) || !validInterval(pause)) return "timer";
  if (focus.p90 - ageSeconds < 10) return "release";
  if (focus.p10 - ageSeconds >= 30 && pause.median < exitPauseMs / 1000)
    return "hold";
  return "timer";
}

/** An estimate of the whole pause, including the time already observed. */
export function predictedBreak(
  pause: Interval | null,
  elapsedAtPrediction: number,
  minimumSeconds = 60,
): boolean {
  return (
    Number.isFinite(elapsedAtPrediction) &&
    elapsedAtPrediction >= 0 &&
    validInterval(pause) &&
    pause.p10 + elapsedAtPrediction >= minimumSeconds
  );
}

export function rhythmCounts(
  samples: readonly KeySample[],
  now: number,
): number[] {
  const bins = Array<number>(6).fill(0);
  for (const sample of samples) {
    const age = now - sample.at;
    if (age >= 0 && age < 60_000) bins[5 - Math.floor(age / 10_000)]++;
  }
  return bins;
}

/** Existing cards may stay in settling; costly, little-used kinds can wait. */
export function skipFragileKind(
  mode: FlowMode,
  weight: number,
  costSeconds: number | null,
): boolean {
  return (
    mode === "settling" &&
    weight < 0.8 &&
    costSeconds !== null &&
    costSeconds >= 30
  );
}

/** Least-used hours first. No preference until at least an hour was observed. */
export function awayHours(profile: FlowProfile, top = 3): number[] {
  const hours = profile.hours.map((minutes, hour) => ({
    hour,
    minutes: Math.max(0, minutes),
  }));
  const total = hours.reduce((sum, h) => sum + h.minutes, 0);
  if (total < 60 || hours.some((h) => !Number.isFinite(h.minutes))) return [];
  return hours
    .filter((h) => h.minutes < total / 24)
    .sort((a, b) => a.minutes - b.minutes || a.hour - b.hour)
    .slice(0, Math.max(0, top))
    .map((h) => h.hour);
}

/** Fire-and-forget pause estimates. All persisted state is rhythm only. */
import type { FlowProfile } from "./flow-profile";
import type { KeySample } from "./flow-state";
import {
  estimate,
  interval,
  type ExtractionRequest,
  type ExtractionResult,
} from "./extraction";
import {
  backOffExtraction,
  extractionWait,
  MAX_RHYTHM_CALLS_PER_SESSION,
  spendExtraction,
} from "./extraction-budget";
import {
  appendPrediction,
  resolvePause,
  resolveRun,
  trustClairic,
  type RhythmPrediction,
} from "./flow-predictions";
import {
  pauseDecision,
  predictedBreak,
  rhythmBaseline,
  rhythmCounts,
  validInterval,
  type RhythmEstimate,
} from "./flow-rhythm";

export const RHYTHM_BREAK_EVENT = "twyne:rhythm-break";
export const ESTIMATE_TIMEOUT_MS = 1_500;
export interface RhythmBreak {
  folioId: string;
  at: number;
  lastKeyAt: number;
  pause: RhythmEstimate["pause"];
  pauseSeconds: number;
}
interface PauseInput {
  now: number;
  lastKeyAt: number;
  runStartedAt: number;
  runSeconds: number;
  deleteRatio: number;
  exitPauseMs: number;
  samples: readonly KeySample[];
  profile: FlowProfile;
  ask?: (request: ExtractionRequest) => Promise<ExtractionResult>;
  current?: () => boolean;
}

export function rhythmRequest(
  input: PauseInput,
  baseline: RhythmEstimate,
): ExtractionRequest {
  const seconds = (values: number[]) =>
    values
      .slice(-24)
      .map((ms) => Math.round(ms / 1000))
      .join(",");
  return {
    state: [
      `run_seconds_csv=${seconds(input.profile.runs)}`,
      `pause_seconds_csv=${seconds(input.profile.pauses)}`,
      `current_run_seconds=${input.runSeconds}`,
      `focus_bout_seconds=${(input.lastKeyAt - input.runStartedAt) / 1000}`,
      `seconds_since_last_key=${(input.now - input.lastKeyAt) / 1000}`,
      `key_events_per_10_seconds_oldest_first=${rhythmCounts(input.samples, input.now).join(",")}`,
      `delete_ratio=${input.deleteRatio}`,
      `reference_exit_pause_seconds=${input.exitPauseMs / 1000}`,
      `local_hour=${new Date(input.now).getHours()}`,
      `empirical_remaining_seconds=${JSON.stringify(baseline)}`,
    ].join("\n"),
    fields: {
      focus_remaining: estimate(
        "Seconds from now to the last keystroke of this rhythmic focus bout. The reference bout ends when a pause reaches the writer's exit pause, regardless of UI decisions. Shorter gaps can resume. Cadence-run history is an empirical baseline, not cognitive focus evidence.",
        { min: 1, max: 3600, unit: "seconds", log: true, step: 1 },
      ),
      pause_length: estimate(
        "Remaining seconds from now until the next keystroke, conditional on the pause already observed. Compare the empirical remaining-pause interval.",
        { min: 1, max: 600, unit: "seconds", log: true, step: 1 },
      ),
    },
  };
}

export class FlowRhythmEstimator {
  log: RhythmPrediction[] = [];
  private pause: RhythmPrediction | null = null;
  private model: RhythmPrediction | null = null;
  private serial = 0;
  private calls = 0;
  private attemptedPauses = new Set<number>();
  private unavailable = false;
  private timeout: ReturnType<typeof setTimeout> | undefined;
  private current: (() => boolean) | undefined;
  constructor(private changed: () => void = () => {}) {}

  begin(input: PauseInput): void {
    if (this.pause?.lastKeyAt === input.lastKeyAt) return;
    this.invalidate();
    const token = this.serial;
    this.current = input.current;
    const baseline = rhythmBaseline(
      input.profile,
      input.runSeconds,
      (input.now - input.lastKeyAt) / 1000,
    );
    this.pause = {
      id: `${input.runStartedAt}:${input.lastKeyAt}`,
      source: "baseline",
      at: input.now,
      lastKeyAt: input.lastKeyAt,
      runStartedAt: input.runStartedAt,
      runSeconds: input.runSeconds,
      pauseSeconds: (input.now - input.lastKeyAt) / 1000,
      estimate: baseline,
    };
    this.log = appendPrediction(this.log, this.pause);
    this.changed();
    if (
      !baseline.focus ||
      !baseline.pause ||
      !input.ask ||
      this.unavailable ||
      this.calls >= MAX_RHYTHM_CALLS_PER_SESSION ||
      this.attemptedPauses.has(input.lastKeyAt) ||
      extractionWait(input.now)
    )
      return;
    this.calls++;
    this.attemptedPauses.add(input.lastKeyAt);
    spendExtraction(input.now);
    const prediction = this.pause;
    let expired = false;
    this.timeout = setTimeout(() => {
      expired = true;
      backOffExtraction();
    }, ESTIMATE_TIMEOUT_MS);
    const fresh = () =>
      !expired &&
      token === this.serial &&
      this.pause === prediction &&
      Date.now() >= input.now &&
      Date.now() - input.now <= ESTIMATE_TIMEOUT_MS &&
      (input.current?.() ?? true);
    void Promise.resolve()
      .then(() => input.ask!(rhythmRequest(input, baseline)))
      .then((result) => {
        if (!result.ok || result.truncated) {
          if (
            fresh() &&
            (result.error === "unconfigured" || result.error === "signed out")
          )
            this.unavailable = true;
          backOffExtraction();
          return;
        }
        if (!fresh()) return;
        const focusAnswer = result.answers?.focus_remaining;
        const pauseAnswer = result.answers?.pause_length;
        const focus = interval(focusAnswer);
        const pause = interval(pauseAnswer);
        if (
          focusAnswer?.type !== "estimate" ||
          pauseAnswer?.type !== "estimate" ||
          typeof focusAnswer.value !== "number" ||
          typeof pauseAnswer.value !== "number" ||
          !Number.isFinite(focusAnswer.value) ||
          !Number.isFinite(pauseAnswer.value) ||
          (focusAnswer.p_null ?? 0) > 0.5 ||
          (pauseAnswer.p_null ?? 0) > 0.5 ||
          !validInterval(focus) ||
          !validInterval(pause) ||
          focus.p10 < 1 ||
          focus.p90 > 3600 ||
          pause.p10 < 1 ||
          pause.p90 > 600
        ) {
          backOffExtraction();
          return;
        }
        // Both sources forecast from the same instant, for a paired comparison.
        this.model = {
          ...prediction,
          source: "clairic",
          estimate: { focus, pause },
        };
        this.log = appendPrediction(this.log, this.model);
        this.changed();
      })
      .catch(() => {
        backOffExtraction();
      })
      .finally(() => {
        if (token === this.serial) clearTimeout(this.timeout);
      });
  }

  selected(): RhythmPrediction | null {
    return this.model && (this.current?.() ?? true) && trustClairic(this.log)
      ? this.model
      : this.pause;
  }
  decision(now: number, exitPauseMs: number) {
    const p = this.selected();
    return p
      ? pauseDecision(p.estimate, exitPauseMs, Math.max(0, (now - p.at) / 1000))
      : "timer";
  }
  breakPrediction(folioId: string): RhythmBreak | null {
    const p = this.selected();
    return p && predictedBreak(p.estimate.pause, p.pauseSeconds)
      ? {
          folioId,
          at: p.at,
          lastKeyAt: p.lastKeyAt,
          pause: p.estimate.pause,
          pauseSeconds: p.pauseSeconds,
        }
      : null;
  }
  finishRun(runStartedAt: number, lastKeyAt: number): void {
    this.log = resolveRun(this.log, runStartedAt, lastKeyAt);
    // A model response may still arrive for this pause; resolve it too.
    if (this.pause?.runStartedAt === runStartedAt)
      this.pause.actualFocus = Math.max(0, (lastKeyAt - this.pause.at) / 1000);
    this.changed();
  }
  key(lastKeyAt: number, now: number): void {
    this.log = resolvePause(this.log, lastKeyAt, now);
    this.invalidate();
    this.changed();
  }
  invalidate(): void {
    this.serial++;
    clearTimeout(this.timeout);
    this.pause = this.model = null;
    this.current = undefined;
  }
}
/** Bounded on-device evidence. Outcomes never depend on the prediction's gate. */
import type { Interval } from "./extraction";
import { validInterval, type RhythmEstimate } from "./flow-rhythm";

export const PREDICTION_LOG_KEY = "flow-rhythm-predictions";
export const MAX_PREDICTIONS = 240;
export const MIN_CALIBRATION_PAIRS = 20;
const CALIBRATION_WINDOW = 50;
export type PredictionSource = "baseline" | "clairic";
export interface RhythmPrediction {
  id: string;
  source: PredictionSource;
  at: number;
  /** Observed focus bout, closed by the ordinary exit pause, never the model. */
  runStartedAt: number;
  lastKeyAt: number;
  runSeconds: number;
  pauseSeconds: number;
  estimate: RhythmEstimate;
  actualFocus?: number;
  actualPause?: number;
}

export function normalizePredictions(value: unknown): RhythmPrediction[] {
  if (!Array.isArray(value)) return [];
  return value
    .filter((p): p is RhythmPrediction => {
      if (!p || typeof p !== "object") return false;
      return (
        typeof p.id === "string" &&
        ["baseline", "clairic"].includes(p.source) &&
        [p.at, p.runStartedAt, p.lastKeyAt, p.runSeconds, p.pauseSeconds].every(
          (n) => typeof n === "number" && Number.isFinite(n) && n >= 0,
        ) &&
        p.estimate &&
        (p.estimate.focus === null || validInterval(p.estimate.focus)) &&
        (p.estimate.pause === null || validInterval(p.estimate.pause)) &&
        [p.actualFocus, p.actualPause].every(
          (n) =>
            n === undefined ||
            (typeof n === "number" && Number.isFinite(n) && n >= 0),
        )
      );
    })
    .slice(-MAX_PREDICTIONS);
}

export function appendPrediction(
  log: readonly RhythmPrediction[],
  prediction: RhythmPrediction,
): RhythmPrediction[] {
  return [...log, prediction].slice(-MAX_PREDICTIONS);
}

export function resolveRun(
  log: readonly RhythmPrediction[],
  runStartedAt: number,
  lastKeyAt: number,
): RhythmPrediction[] {
  return log.map((p) =>
    p.runStartedAt === runStartedAt && p.actualFocus === undefined
      ? { ...p, actualFocus: Math.max(0, (lastKeyAt - p.at) / 1000) }
      : p,
  );
}

export function resolvePause(
  log: readonly RhythmPrediction[],
  lastKeyAt: number,
  nextKeyAt: number,
): RhythmPrediction[] {
  return log.map((p) =>
    p.lastKeyAt === lastKeyAt && p.actualPause === undefined
      ? { ...p, actualPause: Math.max(0, (nextKeyAt - p.at) / 1000) }
      : p,
  );
}

export function pinball(actual: number, predicted: number, q: number): number {
  const error = actual - predicted;
  return error * (error >= 0 ? q : q - 1);
}

export function intervalScore(actual: number, interval: Interval): number {
  return (
    interval.p90 -
    interval.p10 +
    10 * Math.max(0, interval.p10 - actual) +
    10 * Math.max(0, actual - interval.p90)
  );
}

export interface Calibration {
  count: number;
  coverage: number;
  pinball: number;
  intervalScore: number;
}

export function calibration(
  log: readonly RhythmPrediction[],
  source: PredictionSource,
  target: "focus" | "pause",
): Calibration {
  const resolved = log
    .filter(
      (p) =>
        p.source === source &&
        validInterval(p.estimate[target]) &&
        (target === "focus" ? p.actualFocus : p.actualPause) !== undefined,
    )
    .slice(-CALIBRATION_WINDOW);
  let covered = 0,
    loss = 0,
    score = 0;
  for (const p of resolved) {
    const interval = p.estimate[target]!;
    const actual = (target === "focus" ? p.actualFocus : p.actualPause)!;
    covered += Number(actual >= interval.p10 && actual <= interval.p90);
    loss +=
      (pinball(actual, interval.p10, 0.1) +
        pinball(actual, interval.median, 0.5) +
        pinball(actual, interval.p90, 0.9)) /
      3;
    score += intervalScore(actual, interval);
  }
  const count = resolved.length;
  return {
    count,
    coverage: count ? covered / count : 0,
    pinball: count ? loss / count : Infinity,
    intervalScore: count ? score / count : Infinity,
  };
}

/** Compare the same pauses, never two sources' unrelated samples. */
export function trustClairic(log: readonly RhythmPrediction[]): boolean {
  const complete = (p: RhythmPrediction) =>
    validInterval(p.estimate.focus) &&
    validInterval(p.estimate.pause) &&
    p.actualFocus !== undefined &&
    p.actualPause !== undefined;
  const baselines = new Map(
    log
      .filter((p) => p.source === "baseline" && complete(p))
      .map((p) => [p.id, p]),
  );
  const models = log
    .filter((p) => {
      const baseline = baselines.get(p.id);
      return (
        p.source === "clairic" &&
        complete(p) &&
        baseline &&
        baseline.at === p.at &&
        baseline.lastKeyAt === p.lastKeyAt &&
        baseline.runStartedAt === p.runStartedAt &&
        baseline.actualFocus === p.actualFocus &&
        baseline.actualPause === p.actualPause
      );
    })
    .slice(-CALIBRATION_WINDOW);
  if (models.length < MIN_CALIBRATION_PAIRS) return false;
  const paired = [...models, ...models.map((p) => baselines.get(p.id)!)];
  return (["focus", "pause"] as const).every((target) => {
    const model = calibration(paired, "clairic", target);
    const baseline = calibration(paired, "baseline", target);
    return (
      model.coverage >= 0.7 &&
      model.coverage <= 0.9 &&
      model.pinball < baseline.pinball &&
      model.intervalScore < baseline.intervalScore
    );
  });
}

